const providerInstanceConfigEnabledFlag = (config         )                      => {
  if (config === null || typeof config !== "object" || Array.isArray(config)) {
    return undefined;
  }
  const enabled = (config                                  ).enabled;
  return typeof enabled === "boolean" ? enabled : undefined;
};


const DEFAULT_DISABLED_PROVIDER_DRIVERS=new Set(["cursor","grok","fx","kiro","muse","pi","opencode","antigravity"]);
const DEFAULT_ENABLED_DEFAULT_INSTANCES=new Set(["codex","claudeAgent"]);
const isUnconfiguredDefaultInstanceEnabled = (instanceId                    )          =>
  DEFAULT_ENABLED_DEFAULT_INSTANCES.has(instanceId);

const defaultEnabledForDriver = (driver                    )          =>
  !DEFAULT_DISABLED_PROVIDER_DRIVERS.has(driver);

const resolveProviderInstanceEnabled = (
  instance                                                               ,
)          => {
  const configEnabled = providerInstanceConfigEnabledFlag(instance.config);
  if (instance.enabled === false || configEnabled === false) {
    return false;
  }
  return instance.enabled ?? configEnabled ?? defaultEnabledForDriver(instance.driver);
};

const resolveProjectProviderInstanceEnabled = (
  settings                                                                        ,
  projectId                  ,
  instanceId                    ,
)          => {
  const override =
    projectId === null
      ? undefined
      : settings.projectSettingsOverrides[projectId]?.providerInstances?.[instanceId]?.enabled;
  if (override !== undefined) return override;
  const instanceConfig = Object.prototype.hasOwnProperty.call(settings.providerInstances, instanceId)
    ? settings.providerInstances[instanceId]
    : undefined;
  return instanceConfig !== undefined
    ? resolveProviderInstanceEnabled(instanceConfig)
    : isUnconfiguredDefaultInstanceEnabled(instanceId);
};


function exhaustedUsageWindow(
  provider                            ,
  now        ,
  model         ,
) {
  const exhausted = (provider?.usageLimits?.windows ?? []).filter(
    (window) =>
      (window.usedPercent ?? 0) >= 100 &&
      (!window.resetsAt ||
        !Number.isFinite(Date.parse(window.resetsAt)) ||
        Date.parse(window.resetsAt) > now),
  );
  if (model === undefined) return exhausted[0];
  switch (provider?.driver) {
    case "cursor": {
      const api = exhausted.find((window) => window.id === "apiPercentUsed");
      const auto = exhausted.find((window) => window.id === "autoPercentUsed");
      return /^(auto|default|grok|composer)/.test(model) ? auto && api : api;
    }
    case "antigravity": {
      const family = model.match(/^(gemini|claude|gpt)-/)?.[1];
      return exhausted.find((window) => {
        const pool = window.id.match(/^(gemini|claude|gpt|3p)-/)?.[1];
        return (
          pool === undefined ||
          family === undefined ||
          pool === family ||
          (pool === "3p" && (family === "claude" || family === "gpt"))
        );
      });
    }
    case "opencode":
      return exhausted.find(
        (window) => !window.id.startsWith("go_") || model.startsWith("opencode-go/"),
      );
    default:
      return exhausted[0];
  }
}

